	static bool GetEngineBugFixesV222ModuleBase(UInt32* moduleBaseOut);

	template <size_t CodeLength, size_t RelocationCount>
	static bool MatchesEngineBugFixesCode(UInt32 moduleBase, UInt32 rva,
		const UInt8 (&expected)[CodeLength], const UInt32 (&relocations)[RelocationCount])
	{
		if (rva > kEngineBugFixesV222SizeOfImage ||
			CodeLength > kEngineBugFixesV222SizeOfImage - rva ||
			moduleBase + rva < moduleBase ||
			!CanReadMemory(moduleBase + rva, (UInt32)CodeLength))
			return false;

		const UInt32 address = moduleBase + rva;
		UInt32 offset = 0;
		for (size_t i = 0; i < RelocationCount; ++i)
		{
			const UInt32 relocation = relocations[i];
			if (relocation < offset || relocation > CodeLength ||
				sizeof(UInt32) > CodeLength - relocation ||
				!BytesMatch(address + offset, expected + offset, relocation - offset))
				return false;

			UInt32 expectedAddress = 0;
			memcpy(&expectedAddress, expected + relocation, sizeof(expectedAddress));
			expectedAddress += moduleBase - kEngineBugFixesPreferredImageBase;
			if (*(const UInt32*)(address + relocation) != expectedAddress)
				return false;
			offset = relocation + sizeof(UInt32);
		}

		return BytesMatch(address + offset, expected + offset, (UInt32)CodeLength - offset);
	}

	static bool MatchesEngineBugFixesPointer(UInt32 moduleBase, UInt32 rva, UInt32 expected)
	{
		return rva <= kEngineBugFixesV222SizeOfImage - sizeof(UInt32) &&
			moduleBase + rva >= moduleBase &&
			CanReadMemory(moduleBase + rva, sizeof(UInt32)) &&
			*(const UInt32*)(moduleBase + rva) == expected;
	}

	static bool MatchesEngineBugFixesActorCommand(UInt32 moduleBase, UInt32 hookRVA)
	{
		switch (hookRVA)
		{
		case 0x00009B10:
			return MatchesEngineBugFixesCode(moduleBase, hookRVA,
				kEngineBugFixesActorFurnitureBytes, kEngineBugFixesActorFurnitureRelocations) &&
				MatchesEngineBugFixesPointer(moduleBase, 0x00049E78, 0x004F65F8) &&
				MatchesEngineBugFixesPointer(moduleBase, 0x00049E7C, 0x004F65DA);
		case 0x00009B40:
			return MatchesEngineBugFixesCode(moduleBase, hookRVA,
				kEngineBugFixesActorLineOfSightBytes, kEngineBugFixesActorLineOfSightRelocations) &&
				MatchesEngineBugFixesPointer(moduleBase, 0x00049E80, 0x005F2E48) &&
				MatchesEngineBugFixesPointer(moduleBase, 0x00049E84, 0x005F28DA);
		case 0x00009B70:
			return MatchesEngineBugFixesCode(moduleBase, hookRVA,
				kEngineBugFixesActorWalkSpeedBytes, kEngineBugFixesActorWalkSpeedRelocations) &&
				MatchesEngineBugFixesPointer(moduleBase, 0x00049E88, 0x005E35EE) &&
				MatchesEngineBugFixesPointer(moduleBase, 0x00049E8C, 0x005E35E6);
		case 0x00009BA0:
			return MatchesEngineBugFixesCode(moduleBase, hookRVA,
				kEngineBugFixesActorTorchBytes, kEngineBugFixesActorTorchRelocations) &&
				MatchesEngineBugFixesPointer(moduleBase, 0x00049E90, 0x004F84B9) &&
				MatchesEngineBugFixesPointer(moduleBase, 0x00049E94, 0x004F84AF);
		case 0x00009BD0:
			return MatchesEngineBugFixesCode(moduleBase, hookRVA,
				kEngineBugFixesActorFurnitureObjectBytes, kEngineBugFixesActorFurnitureObjectRelocations) &&
				MatchesEngineBugFixesPointer(moduleBase, 0x00049E98, 0x004F66E9) &&
				MatchesEngineBugFixesPointer(moduleBase, 0x00049E9C, 0x004F66C7);
		case 0x00009C00:
			return MatchesEngineBugFixesCode(moduleBase, hookRVA,
				kEngineBugFixesActorFurnitureReferenceBytes, kEngineBugFixesActorFurnitureReferenceRelocations) &&
				MatchesEngineBugFixesPointer(moduleBase, 0x00049EA0, 0x004F6679) &&
				MatchesEngineBugFixesPointer(moduleBase, 0x00049EA4, 0x004F6667);
		case 0x00009C30:
			return MatchesEngineBugFixesCode(moduleBase, hookRVA,
				kEngineBugFixesActorRunningBytes, kEngineBugFixesActorRunningRelocations) &&
				MatchesEngineBugFixesPointer(moduleBase, 0x00049EA8, 0x004F8DE4) &&
				MatchesEngineBugFixesPointer(moduleBase, 0x00049EAC, 0x004F8DDC);
		default:
			return false;
		}
	}

