	static bool GetEngineBugFixesV222ModuleBase(UInt32* moduleBaseOut)
	{
		HMODULE module = GetModuleHandleA("EngineBugFixes.dll");
		if (!module)
			return false;

		const UInt32 moduleBase = (UInt32)module;
		if (!CanReadMemory(moduleBase, sizeof(IMAGE_DOS_HEADER)))
			return false;

		const IMAGE_DOS_HEADER* dos = (const IMAGE_DOS_HEADER*)moduleBase;
		if (dos->e_magic != IMAGE_DOS_SIGNATURE || dos->e_lfanew <= 0)
			return false;

		const UInt32 ntAddress = moduleBase + (UInt32)dos->e_lfanew;
		if (ntAddress < moduleBase || !CanReadMemory(ntAddress, sizeof(IMAGE_NT_HEADERS32)))
			return false;

		const IMAGE_NT_HEADERS32* nt = (const IMAGE_NT_HEADERS32*)ntAddress;
		if (nt->Signature != IMAGE_NT_SIGNATURE ||
			nt->FileHeader.Machine != IMAGE_FILE_MACHINE_I386 ||
			nt->FileHeader.TimeDateStamp != kEngineBugFixesV222TimeDateStamp ||
			nt->OptionalHeader.Magic != IMAGE_NT_OPTIONAL_HDR32_MAGIC ||
			nt->OptionalHeader.SizeOfImage != kEngineBugFixesV222SizeOfImage ||
			nt->OptionalHeader.CheckSum != kEngineBugFixesV222Checksum)
		{
			return false;
		}

		if (moduleBaseOut)
			*moduleBaseOut = moduleBase;
		return true;
	}

	static bool IsEngineBugFixesV222ActorGuard(UInt32 patchSite,
		UInt32 expectedHookRVA,
		UInt32 guardIndex,
		const UInt8* expectedGuardBody,
		UInt32 expectedGuardBodyLength)
	{
		UInt32 moduleBase = 0;
		if (!GetEngineBugFixesV222ModuleBase(&moduleBase))
			return false;

		const UInt8* site = (const UInt8*)patchSite;
		if (site[0] != 0xE9)
			return false;

		const UInt32 target = patchSite + 5 + *(const SInt32*)(site + 1);
		if (target != moduleBase + expectedHookRVA ||
			!CanReadMemory(target, 10 + expectedGuardBodyLength))
		{
			return false;
		}

		const UInt8* hook = (const UInt8*)target;
		if (hook[0] != 0xC7 || hook[1] != 0x05 ||
			*(const UInt32*)(hook + 6) != guardIndex)
		{
			return false;
		}

		const UInt32 counterAddress = *(const UInt32*)(hook + 2);
		if (counterAddress < moduleBase ||
			counterAddress >= moduleBase + kEngineBugFixesV222SizeOfImage)
		{
			return false;
		}

		return BytesMatch(target + 10, expectedGuardBody, expectedGuardBodyLength) &&
			MatchesEngineBugFixesActorCommand(moduleBase, expectedHookRVA);
	}

	static bool IsEngineBugFixesV222CommandNullGuard(UInt32 patchSite,
		UInt32 expectedHookRVA,
		UInt8 expectedSavedRegisterOpcode,
		UInt8 expectedStackCleanup,
		UInt32 expectedHelperRVA,
		UInt32 continuePointerRVA,
		UInt32 expectedContinueSite,
		const UInt8* expectedHelperPrefix,
		UInt32 expectedHelperPrefixLength)
	{
		UInt32 moduleBase = 0;
		if (!GetEngineBugFixesV222ModuleBase(&moduleBase))
			return false;

		const UInt8* site = (const UInt8*)patchSite;
		if (site[0] != 0xE9)
			return false;

		const UInt32 hookAddress = patchSite + 5 + *(const SInt32*)(site + 1);
		if (hookAddress != moduleBase + expectedHookRVA ||
			!CanReadMemory(hookAddress, 15))
		{
			return false;
		}

		const UInt8* hook = (const UInt8*)hookAddress;
		if (hook[0] != expectedSavedRegisterOpcode ||
			hook[1] != 0xE8 ||
			hookAddress + 6 + *(const SInt32*)(hook + 2) != moduleBase + expectedHelperRVA ||
			hook[6] != 0x83 || hook[7] != 0xC4 || hook[8] != expectedStackCleanup ||
			hook[9] != 0xFF || hook[10] != 0x25 ||
			*(const UInt32*)(hook + 11) != moduleBase + continuePointerRVA)
		{
			return false;
		}

		const UInt32 continuePointerAddress = moduleBase + continuePointerRVA;
		if (!CanReadMemory(continuePointerAddress, sizeof(UInt32)) ||
			*(const UInt32*)continuePointerAddress != expectedContinueSite)
		{
			return false;
		}

		const UInt32 helperAddress = moduleBase + expectedHelperRVA;
		if (!CanReadMemory(helperAddress, expectedHelperPrefixLength) ||
			!BytesMatch(helperAddress, expectedHelperPrefix, expectedHelperPrefixLength))
			return false;

		if (expectedHelperRVA == kEngineBugFixesCanHaveFlamesHelperRVA)
			return MatchesEngineBugFixesCode(moduleBase, expectedHelperRVA,
				kEngineBugFixesCanHaveFlamesHelperBytes, kEngineBugFixesCanHaveFlamesHelperRelocations);
		if (expectedHelperRVA == kEngineBugFixesGetAlarmedHelperRVA)
			return MatchesEngineBugFixesCode(moduleBase, expectedHelperRVA,
				kEngineBugFixesGetAlarmedHelperBytes, kEngineBugFixesGetAlarmedHelperRelocations);
		return false;
	}

	static bool IsEngineBugFixesV222CanHaveFlamesGuard()
	{
		return IsEngineBugFixesV222CommandNullGuard(kCanHaveFlamesPatchSite,
			kEngineBugFixesCanHaveFlamesHookRVA,
			0x50,
			0x08,
			kEngineBugFixesCanHaveFlamesHelperRVA,
			kEngineBugFixesCanHaveFlamesContinuePointerRVA,
			kCanHaveFlamesPatchSite + sizeof(kCanHaveFlamesExpectedBytes),
			kEngineBugFixesCanHaveFlamesHelperPrefix,
			sizeof(kEngineBugFixesCanHaveFlamesHelperPrefix));
	}

	static bool IsEngineBugFixesV222GetAlarmedGuard()
	{
		UInt32 moduleBase = 0;
		if (!GetEngineBugFixesV222ModuleBase(&moduleBase) ||
			!IsEngineBugFixesV222CommandNullGuard(kGetAlarmedPatchSite,
				kEngineBugFixesGetAlarmedHookRVA,
				0x51,
				0x04,
				kEngineBugFixesGetAlarmedHelperRVA,
				kEngineBugFixesGetAlarmedContinuePointerRVA,
				kGetAlarmedPatchSite + sizeof(kGetAlarmedExpectedBytes),
				kEngineBugFixesGetAlarmedHelperPrefix,
				sizeof(kEngineBugFixesGetAlarmedHelperPrefix)))
		{
			return false;
		}

		const UInt32 helperAddress = moduleBase + kEngineBugFixesGetAlarmedHelperRVA;
		const UInt32 emptyStringAddress = moduleBase + kEngineBugFixesEmptyStringRVA;
		return CanReadMemory(helperAddress + 0x1D, 5) &&
			((const UInt8*)helperAddress)[0x1D] == 0xBE &&
			*(const UInt32*)(helperAddress + 0x1E) == emptyStringAddress &&
			CanReadMemory(emptyStringAddress, 1) &&
			*(const char*)emptyStringAddress == 0;
	}

	static bool IsEngineBugFixesV222SpellPurchaseGuard()
	{
		UInt32 moduleBase = 0;
		if (!GetEngineBugFixesV222ModuleBase(&moduleBase))
			return false;

		const UInt8* site = (const UInt8*)kSpellPurchaseTilePatchSite;
		if (site[0] != 0xE9 || site[5] != 0x90)
			return false;

		const UInt32 hookAddress = kSpellPurchaseTilePatchSite + 5 + *(const SInt32*)(site + 1);
		if (hookAddress != moduleBase + kEngineBugFixesSpellPurchaseHookRVA ||
			!CanReadMemory(hookAddress, 31))
		{
			return false;
		}

		const UInt8* hook = (const UInt8*)hookAddress;
		if (hook[0] != 0x8B || hook[1] != 0x4C || hook[2] != 0x24 || hook[3] != 0x0C ||
			hook[4] != 0x85 || hook[5] != 0xC9 || hook[6] != 0x74 || hook[7] != 0x0C ||
			hook[8] != 0xD9 || hook[9] != 0x05 ||
			*(const UInt32*)(hook + 10) != moduleBase + kEngineBugFixesSpellPurchaseFloatRVA ||
			hook[14] != 0xFF || hook[15] != 0x25 ||
			*(const UInt32*)(hook + 16) != moduleBase + kEngineBugFixesSpellPurchaseContinuePointerRVA ||
			hook[20] != 0xE8 ||
			hookAddress + 25 + *(const SInt32*)(hook + 21) != moduleBase + kEngineBugFixesSpellPurchaseLogHelperRVA ||
			hook[25] != 0xFF || hook[26] != 0x25 ||
			*(const UInt32*)(hook + 27) != moduleBase + kEngineBugFixesSpellPurchaseNullContinuePointerRVA)
		{
			return false;
		}

		const UInt32 continuePointer = moduleBase + kEngineBugFixesSpellPurchaseContinuePointerRVA;
		const UInt32 nullContinuePointer = moduleBase + kEngineBugFixesSpellPurchaseNullContinuePointerRVA;
		return CanReadMemory(continuePointer, sizeof(UInt32)) &&
			CanReadMemory(nullContinuePointer, sizeof(UInt32)) &&
			*(const UInt32*)continuePointer == kSpellPurchaseTileContinueSite &&
			*(const UInt32*)nullContinuePointer == kSpellPurchaseTileNullSite;
	}

	static bool IsEngineBugFixesV222DropItemFix()
	{
		UInt32 moduleBase = 0;
		if (!GetEngineBugFixesV222ModuleBase(&moduleBase) ||
			!BytesMatch(kDropItemNullExtraListContextAddr,
				kDropItemNullExtraListFixedBytes,
				sizeof(kDropItemNullExtraListFixedBytes)))
		{
			return false;
		}

		const UInt32 installerAddress = moduleBase + kEngineBugFixesDropItemInstallerRVA;
		if (!CanReadMemory(installerAddress, 18))
			return false;

		const UInt8* installer = (const UInt8*)installerAddress;
		return installer[0] == 0x6A && installer[1] == 0x14 &&
			installer[2] == 0x68 &&
			*(const UInt32*)(installer + 3) == kDropItemNullExtraListPatchSite + 1 &&
			installer[7] == 0xE8 &&
			installerAddress + 12 + *(const SInt32*)(installer + 8) == moduleBase + kEngineBugFixesWriteByteRVA &&
			installer[12] == 0x83 && installer[13] == 0xC4 && installer[14] == 0x08 &&
			installer[15] == 0xB0 && installer[16] == 0x01 && installer[17] == 0xC3;
	}

	static DropItemPatchState GetDropItemPatchState()
	{
		const UInt32 replacementTarget = kDropItemNullExtraListPatchSite + 2 +
			(SInt32)(signed char)kDropItemNullExtraListReplacementBytes[1];
		const UInt32 intermediateTarget = kDropItemNullExtraListContextAddr +
			sizeof(kDropItemNullExtraListExpectedBytes) +
			*(const SInt32*)(kDropItemNullExtraListExpectedBytes + 30);
		if (replacementTarget != kDropItemNullExtraListIntermediateSite ||
			intermediateTarget != kDropItemNullExtraListContinueSite)
		{
			Log("refusing to patch: invalid compiled DropItem branch contract");
			return kDropItemPatchMismatch;
		}

		if (BytesMatch(kDropItemNullExtraListContextAddr,
				kDropItemNullExtraListExpectedBytes,
				sizeof(kDropItemNullExtraListExpectedBytes)))
		{
			return kDropItemPatchNeedsInstall;
		}

		if (IsEngineBugFixesV222DropItemFix())
		{
			Log("accepted EngineBugFixes v2.22 DropItem null-extra-list branch at %08X",
				kDropItemNullExtraListPatchSite);
			return kDropItemPatchAlreadyFixed;
		}

		char expectedText[192];
		char actualText[192];
		FormatBytes(kDropItemNullExtraListExpectedBytes,
			sizeof(kDropItemNullExtraListExpectedBytes),
			expectedText,
			sizeof(expectedText));
		FormatBytes((const UInt8*)kDropItemNullExtraListContextAddr,
			sizeof(kDropItemNullExtraListExpectedBytes),
			actualText,
			sizeof(actualText));
		Log("refusing to patch: unexpected DropItem null-extra-list context at %08X; expected [%s], actual [%s]",
			kDropItemNullExtraListContextAddr,
			expectedText,
			actualText);
		return kDropItemPatchMismatch;
	}

	static bool IsEngineBugFixesV222CellChangedRefHook(UInt32 patchSite,
		UInt32 expectedHookRVA,
		UInt32 continuePointerRVA,
		UInt32 expectedContinueSite)
	{
		UInt32 moduleBase = 0;
		if (!GetEngineBugFixesV222ModuleBase(&moduleBase))
			return false;

		const UInt8* site = (const UInt8*)patchSite;
		if (site[0] != 0xE9)
			return false;

		const UInt32 hookAddress = patchSite + 5 + *(const SInt32*)(site + 1);
		if (hookAddress != moduleBase + expectedHookRVA ||
			!CanReadMemory(hookAddress, 26))
		{
			return false;
		}

		const UInt8* hook = (const UInt8*)hookAddress;
		if (hook[0] != 0xFF || hook[1] != 0x74 || hook[2] != 0x24 || hook[3] != 0x1C ||
			hook[4] != 0xFF || hook[5] != 0x74 || hook[6] != 0x24 || hook[7] != 0x1C ||
			hook[8] != 0x56 || hook[9] != 0x57 || hook[10] != 0xE8 ||
			hookAddress + 15 + *(const SInt32*)(hook + 11) !=
				moduleBase + kEngineBugFixesCellChangedRefHelperRVA ||
			hook[15] != 0x83 || hook[16] != 0xC4 || hook[17] != 0x10 ||
			hook[18] != 0x8B || hook[19] != 0xF0 ||
			hook[20] != 0xFF || hook[21] != 0x25 ||
			*(const UInt32*)(hook + 22) != moduleBase + continuePointerRVA)
		{
			return false;
		}

		const UInt32 continuePointerAddress = moduleBase + continuePointerRVA;
		return CanReadMemory(continuePointerAddress, sizeof(UInt32)) &&
			*(const UInt32*)continuePointerAddress == expectedContinueSite;
	}

	static bool IsEngineBugFixesV222CellChangedRefFix()
	{
		UInt32 moduleBase = 0;
		if (!GetEngineBugFixesV222ModuleBase(&moduleBase) ||
			!IsEngineBugFixesV222CellChangedRefHook(kCellChangedRefCellLoadPatchSite,
				kEngineBugFixesCellChangedRefCellHookRVA,
				kEngineBugFixesCellChangedRefCellContinuePointerRVA,
				kCellChangedRefCellLoadContinueSite) ||
			!IsEngineBugFixesV222CellChangedRefHook(kCellChangedRefWorldLoadPatchSite,
				kEngineBugFixesCellChangedRefWorldHookRVA,
				kEngineBugFixesCellChangedRefWorldContinuePointerRVA,
				kCellChangedRefWorldLoadContinueSite))
		{
			return false;
		}

		return MatchesEngineBugFixesCode(moduleBase, kEngineBugFixesCellChangedRefHelperRVA,
			kEngineBugFixesCellChangedRefHelperBytes, kEngineBugFixesCellChangedRefHelperRelocations);
	}

	static CellChangedRefPatchState GetCellChangedRefPatchState()
	{
		const bool cellVanilla = BytesMatch(kCellChangedRefCellLoadPatchSite,
			kCellChangedRefCellLoadExpectedBytes,
			sizeof(kCellChangedRefCellLoadExpectedBytes));
		const bool worldVanilla = BytesMatch(kCellChangedRefWorldLoadPatchSite,
			kCellChangedRefWorldLoadExpectedBytes,
			sizeof(kCellChangedRefWorldLoadExpectedBytes));
		if (cellVanilla && worldVanilla)
			return kCellChangedRefPatchNeedsInstall;

		if (IsEngineBugFixesV222CellChangedRefFix())
		{
			Log("accepted EngineBugFixes v2.22 changed-reference reuse hooks at %08X/%08X",
				kCellChangedRefCellLoadPatchSite,
				kCellChangedRefWorldLoadPatchSite);
			return kCellChangedRefPatchAlreadyFixed;
		}

		char cellExpected[192];
		char cellActual[192];
		char worldExpected[192];
		char worldActual[192];
		FormatBytes(kCellChangedRefCellLoadExpectedBytes,
			sizeof(kCellChangedRefCellLoadExpectedBytes),
			cellExpected,
			sizeof(cellExpected));
		FormatBytes((const UInt8*)kCellChangedRefCellLoadPatchSite,
			sizeof(kCellChangedRefCellLoadExpectedBytes),
			cellActual,
			sizeof(cellActual));
		FormatBytes(kCellChangedRefWorldLoadExpectedBytes,
			sizeof(kCellChangedRefWorldLoadExpectedBytes),
			worldExpected,
			sizeof(worldExpected));
		FormatBytes((const UInt8*)kCellChangedRefWorldLoadPatchSite,
			sizeof(kCellChangedRefWorldLoadExpectedBytes),
			worldActual,
			sizeof(worldActual));
		Log("refusing to patch: unexpected changed-reference load bytes; cell %08X expected [%s], actual [%s]; world %08X expected [%s], actual [%s]",
			kCellChangedRefCellLoadPatchSite,
			cellExpected,
			cellActual,
			kCellChangedRefWorldLoadPatchSite,
			worldExpected,
			worldActual);
		return kCellChangedRefPatchMismatch;
	}

	static CommandNullGuardPatchState GetCommandNullGuardPatchState(const char* name,
		UInt32 patchSite,
		const UInt8* expectedBytes,
		UInt32 expectedLength,
		bool engineBugFixesGuardPresent)
	{
		if (BytesMatch(patchSite, expectedBytes, expectedLength))
			return kCommandNullGuardPatchNeedsInstall;

		if (engineBugFixesGuardPresent)
		{
			Log("accepted EngineBugFixes v2.22 %s null guard at %08X", name, patchSite);
			return kCommandNullGuardPatchAlreadyGuarded;
		}

		char expectedText[128];
		char actualText[128];
		FormatBytes(expectedBytes, expectedLength, expectedText, sizeof(expectedText));
		FormatBytes((const UInt8*)patchSite, expectedLength, actualText, sizeof(actualText));
		Log("refusing to patch: unexpected %s null-guard bytes at %08X; expected [%s], actual [%s]",
			name,
			patchSite,
			expectedText,
			actualText);
		return kCommandNullGuardPatchMismatch;
	}

	static ActorProcessCommandPatchState GetActorProcessCommandPatchState(
		const char* name,
		UInt32 patchSite,
		const UInt8* expectedBytes,
		UInt32 expectedLength,
		UInt32 engineBugFixesHookRVA,
		UInt32 engineBugFixesGuardIndex,
		const UInt8* engineBugFixesGuardBody,
		UInt32 engineBugFixesGuardBodyLength)
	{
		if (BytesMatch(patchSite, expectedBytes, expectedLength))
			return kActorProcessCommandPatchNeedsInstall;

		if (IsEngineBugFixesV222ActorGuard(patchSite,
				engineBugFixesHookRVA,
				engineBugFixesGuardIndex,
				engineBugFixesGuardBody,
				engineBugFixesGuardBodyLength))
		{
			Log("accepted EngineBugFixes v2.22 %s process guard at %08X",
				name,
				patchSite);
			return kActorProcessCommandPatchAlreadyGuarded;
		}

		char expectedText[128];
		char actualText[128];
		FormatBytes(expectedBytes, expectedLength, expectedText, sizeof(expectedText));
		FormatBytes((const UInt8*)patchSite, expectedLength, actualText, sizeof(actualText));
		Log("refusing to patch: unexpected %s process guard bytes at %08X; expected [%s], actual [%s]",
			name,
			patchSite,
			expectedText,
			actualText);
		return kActorProcessCommandPatchMismatch;
	}

	static TESWorldSpaceOFSTPatchState GetTESWorldSpaceOFSTPatchState()
	{
		if (BytesMatch(kTESWorldSpaceLoadOFSTPatchSite,
				kTESWorldSpaceLoadOFSTExpectedBytes,
				sizeof(kTESWorldSpaceLoadOFSTExpectedBytes)))
		{
			return kTESWorldSpaceOFSTPatchNeedsInstall;
		}

		const UInt8* site = (const UInt8*)kTESWorldSpaceLoadOFSTPatchSite;
		if (site[0] == 0xE9)
		{
			UInt32 target = kTESWorldSpaceLoadOFSTPatchSite + 5 + *(const SInt32*)(site + 1);
			if (target == kTESWorldSpaceLoadOFSTContinueSite &&
				BytesMatch(kTESWorldSpaceLoadOFSTPatchSite + 5,
					kTESWorldSpaceLoadOFSTExpectedBytes + 5,
					sizeof(kTESWorldSpaceLoadOFSTExpectedBytes) - 5))
			{
				Log("TESWorldSpace WRLD OFST load already skipped at %08X; treating WRLD/OFST offset policy as externally owned",
					kTESWorldSpaceLoadOFSTPatchSite);
				return kTESWorldSpaceOFSTPatchExternallySkipped;
			}
		}

		char expectedText[512];
		char actualText[512];
		FormatBytes(kTESWorldSpaceLoadOFSTExpectedBytes,
			sizeof(kTESWorldSpaceLoadOFSTExpectedBytes),
			expectedText,
			sizeof(expectedText));
		FormatBytes(site,
			sizeof(kTESWorldSpaceLoadOFSTExpectedBytes),
			actualText,
			sizeof(actualText));

		Log("refusing to patch: unexpected TESWorldSpace WRLD OFST load bytes at %08X; expected [%s], actual [%s]",
			kTESWorldSpaceLoadOFSTPatchSite,
			expectedText,
			actualText);
		return kTESWorldSpaceOFSTPatchMismatch;
	}

